function extractResultOutputs(result) {
  if (!result || typeof result !== "object")
    return { urls: [] };
  const record2 = result;
  const urls = [];
  if (Array.isArray(record2.resultUrls)) {
    urls.push(...record2.resultUrls.filter((url2) => typeof url2 === "string"));
  }
  if (Array.isArray(record2.data)) {
    for (const track of record2.data) {
      const audio = track?.audio_url;
      if (typeof audio === "string")
        urls.push(audio);
    }
  }
  return {
    urls: [...new Set(urls)],
    ...record2.resultObject !== void 0 ? { resultObject: record2.resultObject } : {}
  };
}
